BEGIN;
WITH ranked AS (SELECT id,category,row_number() OVER(PARTITION BY category ORDER BY prompt,id) AS rn FROM public.question_bank WHERE source_kind='starter_draft')
DELETE FROM public.question_bank q USING ranked r WHERE q.id=r.id AND (r.category NOT IN ('LTC Billing','Coupons & Follow-Up') OR r.rn>5);
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 1: Refill Processing','Before processing a refill, which checks should be completed?',ARRAY['Confirm only that the medication appears on the profile','Verify active coverage, prescription validity, authorized refills, and whether the refill is due','Copy the previous claim without reviewing it','Process the claim first and check eligibility afterward']::text[],'basic',false,'training_material',1) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,1,'A previous fill does not establish current eligibility or refill readiness.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 1: Refill Processing','A medication has not been filled for more than six months. What should the biller do?',ARRAY['Automatically bill it because it remains on the profile','Delete the patient’s prescription history','Change its day supply to 30 days','Confirm current use or escalate before billing']::text[],'basic',false,'training_material',2) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,3,'Dormant medications should not be automatically billed.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 1: Refill Processing','What patient communication was emphasized in the initial refill training?',ARRAY['Confirm pickup or delivery before processing under the applicable workflow','Ask the patient to choose the claim’s NDC','Contact the patient only after several unsuccessful deliveries','Tell the patient that every refill must be picked up in person']::text[],'basic',false,'training_material',3) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,0,'The training emphasized confirming the patient’s pickup or delivery plan.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 1: Refill Processing','After billing a refill, why should the biller filter and review the patient profile?',ARRAY['To hide all previously paid claims','To remove every expired prescription automatically','To identify duplicates, overlapping therapies, and other outstanding work','To replace the pharmacist’s clinical review']::text[],'basic',false,'training_material',4) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,2,'Processing is not complete until related profile issues have been reviewed.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 1: Refill Processing','A verified new prescription changes a medication’s strength. What should happen to the outdated strength?',ARRAY['Keep both available for automatic billing','Address the outdated strength under the approved discontinuation workflow and document the change','Bill both strengths to see which claim pays','Remove all records of the previous treatment']::text[],'basic',false,'training_material',5) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,1,'The old strength should not remain available for accidental dispensing.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 2: New Prescription Processing','Which three selections were identified as especially critical during new eRx processing?',ARRAY['Patient, prescriber, and medication','Delivery driver, payment method, and pickup time','Label color, printer, and workstation','Cash price, follow-up date, and staff initials']::text[],'basic',false,'training_material',6) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,0,'Errors in these selections can affect the entire prescription workflow.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 2: New Prescription Processing','What patient-lookup approach was emphasized?',ARRAY['Select the first matching surname','Match only the patient’s phone number','Search only by the medication name','Use DOB as an anchor, then verify other identifying information']::text[],'basic',false,'training_material',7) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,3,'DOB helps narrow the search, but additional identifiers must still be checked.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 2: New Prescription Processing','Several prescriber records have similar names. What is the best next step?',ARRAY['Choose whichever record appears first','Choose the record used for an unrelated patient','Match the NPI and relevant license, address, or clinic details to the prescription','Skip prescriber verification if the medication is familiar']::text[],'basic',false,'training_material',8) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,2,'Similar names are not sufficient verification.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 2: New Prescription Processing','How should the medication and NDC be selected?',ARRAY['Always choose the highlighted item','Verify the drug, strength, dosage form, package, and appropriate plan-accepted NDC','Always choose the cheapest item regardless of formulation','Use any NDC associated with the same drug name']::text[],'basic',false,'training_material',9) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,1,'Highlighting and previous fills are references, not substitutes for verification.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 2: New Prescription Processing','During the July 21 eRx import exercise, which action did the training specify?',ARRAY['Ignore','Delete Selected','Close Without Saving','Update Selected']::text[],'basic',false,'training_material',10) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,3,'The session specifically reinforced using “Update Selected,” not “Ignore.”' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 3: Insurance Billing Basics','What was the training’s usual default for Medicaid/Class A patients under 65, subject to approved exceptions and current policy?',ARRAY['A 30-day supply','A 90-day supply in every case','The largest available package regardless of use','Cash billing only']::text[],'basic',false,'training_material',11) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,0,'The historical default was commonly 30 days, not a universal rule for every payer or product.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 3: Insurance Billing Basics','When is a 90-day commercial claim appropriate under the training guidance?',ARRAY['Whenever the patient is under 65','Whenever the medication has been filled before','When the prescription and plan permit the 90-day quantity','Whenever a 30-day claim rejects']::text[],'basic',false,'training_material',12) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,2,'Both prescription authorization and payer coverage matter.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 3: Insurance Billing Basics','What is the correct sequence for secondary billing?',ARRAY['Bill secondary first and ignore primary coverage','Obtain the primary payer’s response, then use secondary coverage if active and applicable','Bill whichever plan paid the most last time','Submit both without reviewing either response']::text[],'basic',false,'training_material',13) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,1,'Secondary processing depends on the primary response and valid secondary coverage.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 3: Insurance Billing Basics','Using the training’s cash-price formula, what is the price of a prescription item with an acquisition cost of $8 and a $10 dispensing fee?',ARRAY['$12','$18','$20','$22']::text[],'basic',false,'training_material',14) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,3,'($8 × 1.5) + $10 = **$22**. Confirm current pricing policy before quoting a patient.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 4: SIG Codes and Documentation','What does “1 tablet BID” mean?',ARRAY['One tablet twice daily','One tablet every other day','Two tablets once weekly','One tablet at bedtime only']::text[],'basic',false,'training_material',15) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,0,'' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 4: SIG Codes and Documentation','A prescription says only “use as directed,” and the dose cannot be established from authorized information. What should happen next?',ARRAY['Copy a different patient’s directions','Assume once-daily use','Obtain clarification through the approved workflow before entering an explicit SIG','Select whichever frequency produces a paid claim']::text[],'basic',false,'training_material',16) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,2,'Directions must be supported, not invented.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 4: SIG Codes and Documentation','Which instruction best demonstrates patient-friendly SIG wording?',ARRAY['“1T PO BID” without translation','“Take one tablet by mouth twice daily”','“Use medication normally”','“Follow standard regimen”']::text[],'basic',false,'training_material',17) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,1,'Clear instructions communicate the dose, route, and frequency.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 4: SIG Codes and Documentation','When may a note state “per prescriber”?',ARRAY['Whenever the biller thinks the prescriber would agree','Whenever the previous fill used the same directions','Whenever the claim pays','When the instruction or clarification is actually supported by documented prescriber authorization']::text[],'basic',false,'training_material',18) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,3,'Documentation must not imply a confirmation that never occurred.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 5: Common Rejections and Troubleshooting','Which distinction between codes 75 and 70 matches the training?',ARRAY['Code 75 generally indicates PA required; code 70 generally indicates non-formulary coverage issues','Both always mean refill too soon','Code 70 always guarantees approval after PA','Both require changing the patient’s demographics']::text[],'basic',false,'training_material',19) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,0,'Read the full payer message; a non-formulary rejection is not automatically solved by PA.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 5: Common Rejections and Troubleshooting','A claim rejects as refill too soon and provides a next-allowed date. What is the appropriate routine response?',ARRAY['Change the previous fill date','Use an override solely to obtain payment','Document or schedule the refill for the payer-allowed date','Submit the same claim repeatedly without changes']::text[],'basic',false,'training_material',20) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,2,'Overrides require a legitimate, supported reason.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 5: Common Rejections and Troubleshooting','A rejection message specifies that the brand product is required. What should the biller review?',ARRAY['Whether the patient can be moved to an unrelated medication','The appropriate brand NDC and DAW requirements supported by the prescription or payer message','Whether the prescription date can be changed','Whether removing the SIG makes the claim payable']::text[],'basic',false,'training_material',21) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,1,'The selected product and claim coding must remain supported.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 5: Common Rejections and Troubleshooting','A 9E/90E rejection indicates a quantity/package mismatch. What should be checked?',ARRAY['The patient’s preferred delivery time','Whether the medication’s price can be increased','Whether the follow-up tag can be removed','Whether the submitted quantity matches the selected NDC’s package size and billing unit']::text[],'basic',false,'training_material',22) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,3,'Correct the supported quantity and recalculate day supply when necessary.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 5: Common Rejections and Troubleshooting','What is the appropriate response to a step-therapy rejection such as code 608?',ARRAY['Coordinate a prescriber-approved covered alternative or a PA supported by trial/failure history','Change the NDC repeatedly without reviewing the message','Automatically dispense a different therapy without authorization','Mark the claim paid manually']::text[],'basic',false,'training_material',23) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,0,'Step therapy concerns treatment requirements, not simply product selection.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 5: Common Rejections and Troubleshooting','A claim requires a DUR override. What should the biller do?',ARRAY['Enter any previously successful override combination','Remove the warning without review','Obtain the required pharmacist or approved-policy review before using supported DUR entries','Change the patient’s identity to bypass the rejection']::text[],'basic',false,'training_material',24) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,2,'A DUR response must reflect an actual reviewed issue and appropriate intervention.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 6: Follow-Up Tags and Queue Management','A claim genuinely requires PA. What is the appropriate follow-up action?',ARRAY['Leave it without a tag or owner','Add the approved PA-required tag and route it through the site’s PA workflow','Delete the prescription immediately','Mark the issue resolved before approval']::text[],'basic',false,'training_material',25) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,1,'Site-specific filing or unbilled handling should follow current policy.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 6: Follow-Up Tags and Queue Management','When should a resolved follow-up tag be cleared?',ARRAY['Only during the next annual review','After the same issue generates another task','Never, because all tags should stay active','Promptly after resolution is confirmed and documented']::text[],'basic',false,'training_material',26) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,3,'Stale tags create duplicate work and obscure unresolved issues.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 6: Follow-Up Tags and Queue Management','Which queue-management approach was taught for patients with several follow-up items?',ARRAY['Use RX Review filters and group or sort by patient to address related items together','Work only the newest item and ignore the rest','Remove every tag before reviewing the profile','Sort only by medication price']::text[],'basic',false,'training_material',27) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,0,'' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Module 6: Follow-Up Tags and Queue Management','An inexpensive OTC item is not covered, with no indication that PA is appropriate. What approach did the training favor?',ARRAY['Automatically submit a PA for every OTC rejection','Leave the item unresolved indefinitely','Review an approved cash/front-of-store option or an appropriate alternative','Change the diagnosis solely to obtain payment']::text[],'basic',false,'training_material',28) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,2,'Not every noncoverage issue belongs in the PA queue.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Practical Application: Medication-Specific Calculations','A long-acting U100 insulin box contains five 3-mL pens. How many units are in one box?',ARRAY['150 units','1,500 units','3,000 units','5,000 units']::text[],'basic',false,'training_material',29) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,1,'5 × 3 mL × 100 units/mL = **1,500 units**.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Practical Application: Medication-Specific Calculations','A rapid-acting insulin prescription specifies 18 units three times daily. A box contains 1,500 units. What is the approximate supply, rounded to the nearest whole day for this exercise?',ARRAY['18 days','54 days','83 days','28 days']::text[],'basic',false,'training_material',30) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,3,'Daily use = 18 × 3 = 54 units; 1,500 ÷ 54 ≈ **28 days**.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Practical Application: Medication-Specific Calculations','Which statement about insulin after-opening stability is correct?',ARRAY['Verify the exact product’s manufacturer labeling rather than assuming every insulin lasts 28 days','Every insulin pen and vial has identical after-opening stability','Stability can be ignored if the claim pays','Package volume alone determines the usable supply']::text[],'basic',false,'training_material',31) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,0,'Product-specific stability can limit the usable duration.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Practical Application: Medication-Specific Calculations','A 100-g gel is prescribed at 1 g every six hours. Assuming four applications daily, what is the calculated supply?',ARRAY['10 days','20 days','25 days','100 days']::text[],'basic',false,'training_material',32) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,2,'4 × 1 g = 4 g/day; 100 ÷ 4 = **25 days**.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Practical Application: Medication-Specific Calculations','A 120-mL shampoo is used at 1 mL twice weekly. What is the arithmetic duration before applying any validity, stability, or payer limit?',ARRAY['60 days','420 days','120 days','365 days']::text[],'basic',false,'training_material',33) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,1,'120 ÷ 2 = 60 weeks; 60 × 7 = **420 days**. This is not automatically the permitted claim day supply.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Practical Application: Medication-Specific Calculations','A 5-mL ophthalmic solution contains 20 drops/mL for this exercise. The verified directions are one drop in each eye twice daily. What is the calculated supply?',ARRAY['10 days','20 days','50 days','25 days']::text[],'basic',false,'training_material',34) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,3,'5 × 20 = 100 drops; daily use is 4 drops; 100 ÷ 4 = **25 days**.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Practical Application: Medication-Specific Calculations','For this exercise, a 4-mL ophthalmic suspension contains 15 drops/mL. The directions are one drop in one affected eye three times daily. What is the calculated supply?',ARRAY['20 days','15 days','30 days','60 days']::text[],'basic',false,'training_material',35) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,0,'4 × 15 = 60 drops; 60 ÷ 3 = **20 days**.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Practical Application: Medication-Specific Calculations','An inhaler contains 200 puffs. The directions are two puffs every six hours. Assuming four doses daily, what is the calculated supply?',ARRAY['20 days','50 days','25 days','100 days']::text[],'basic',false,'training_material',36) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,2,'Daily use = 2 × 4 = 8 puffs; 200 ÷ 8 = **25 days**.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Practical Application: Medication-Specific Calculations','A maintenance inhaler contains 120 puffs. Its verified directions are two puffs twice daily. What is the calculated supply?',ARRAY['15 days','30 days','60 days','120 days']::text[],'basic',false,'training_material',37) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,1,'Daily use = 4 puffs; 120 ÷ 4 = **30 days**.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Practical Application: Medication-Specific Calculations','An albuterol nebulizer prescription supplies 360 mL in 3-mL unit-dose vials. At a maximum of one vial every six hours, what is the calculated supply?',ARRAY['15 days','60 days','120 days','30 days']::text[],'basic',false,'training_material',38) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,3,'360 ÷ 3 = 120 vials; 120 ÷ 4 daily doses = **30 days**.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Practical Application: Medication-Specific Calculations','A budesonide nebulizer box contains 60 mL in 2-mL vials. The verified directions are one vial twice daily. How long does one box last?',ARRAY['15 days','20 days','30 days','60 days']::text[],'basic',false,'training_material',39) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,0,'60 ÷ 2 = 30 vials; 30 ÷ 2 = **15 days**.' FROM item;
WITH item AS (INSERT INTO public.question_bank(category,prompt,options,difficulty,active,source_kind,source_number) VALUES ('Practical Application: Medication-Specific Calculations','A pediatric liquid is prescribed at 10 mL three times daily for seven days. How much liquid is required for the prescribed course, before considering bottle-size adjustments?',ARRAY['120 mL','180 mL','210 mL','240 mL']::text[],'basic',false,'training_material',40) ON CONFLICT DO NOTHING RETURNING id)
INSERT INTO private.answer_keys(question_id,correct_option_index,explanation) SELECT id,2,'10 × 3 × 7 = **210 mL**. Any package-size adjustment must follow the approved dispensing workflow.' FROM item;
COMMIT;